export function invoiceRoute(request, database) {
  if (!request.session?.userId) return { status: 401 };
  const invoice = database.findInvoice(request.params.id);
  return invoice ? { status: 200, body: invoice } : { status: 404 };
}

export function settingsRoute(request, database) {
  if (!request.session?.userId) return { status: 401 };
  return { status: 200, body: database.findSettings(request.session.tenantId) };
}

